apiVersion: v1
kind: ConfigMap
metadata:
  name: {{ include "reporting.fullname" . }}-settings
  labels:
    {{- include "reporting.labels" . | nindent 4 }}
data:
  REPORT_TIMEZONE: {{ .Values.timezone | quote }}
  DB_HOST: {{ .Values.db.host | quote }}
  DB_USER: {{ .Values.db.user | quote }}
  DB_PASSWORD: {{ .Values.db.password | quote }}
  EXPORT_FORMAT: {{ .Values.exportFormat | default "csv" | quote }}
